import assert from 'node:assert/strict';
import fs from 'node:fs';
import crypto from 'node:crypto';
import ts from 'typescript';
import vm from 'node:vm';
import {execFileSync} from 'node:child_process';
import {loadPlayerCatalogue,loadRepositoryModule} from './load-player-catalogue.mjs';
const base='7b19459c09494f36210e1b3b7017bedf0868ec8d';
const before=execFileSync('git',['show','7b19459c09494f36210e1b3b7017bedf0868ec8d:lib/chemistry.ts'],{encoding:'utf8'});
const mod={exports:{}};vm.runInNewContext(ts.transpileModule(before,{compilerOptions:{module:ts.ModuleKind.CommonJS}}).outputText,{module:mod,exports:mod.exports});
const {FORMATIONS}=loadRepositoryModule('lib/chemistry.ts');const {spotsFor}=loadRepositoryModule('lib/mobileLayout.ts');
const shape=id=>FORMATIONS.find(f=>f.id===id),positions=id=>shape(id).lines.flat().map(s=>s.position);
for(const id of ['433-2','433-3','433-4'])assert.deepEqual(shape(id).lines.flat().map(s=>s.id).sort(),Array.from(mod.exports.FORMATIONS.find(f=>f.id===id).lines.flat(),s=>s.id).sort(),'Saved squad slot IDs must survive '+id);
assert.equal(positions('433-2').filter(p=>p==='CDM').length,1);assert.equal(positions('433-2').filter(p=>p==='CM').length,2);
assert.equal(positions('433-3').filter(p=>p==='CDM').length,2);assert.equal(positions('433-3').filter(p=>p==='CM').length,1);assert(!positions('433-3').includes('CAM'));assert(positions('433-3').includes('ST'));
assert.equal(positions('433-4').filter(p=>p==='CM').length,2);assert.equal(positions('433-4').filter(p=>p==='CAM').length,1);assert(!positions('433-4').includes('CDM'));
assert(spotsFor(shape('433-3')).cam.y>spotsFor(shape('433-4')).cam.y,'Defend central midfielder must sit deeper than Attack CAM');
assert(spotsFor(shape('433-3')).lcm.y>spotsFor(shape('433-4')).lcm.y,'Defend pivots must sit deeper than Attack CMs');
const home=fs.readFileSync('app/(tabs)/index.tsx','utf8');assert(!home.includes('HomeSeason2Overview'));assert(fs.existsSync('components/HomeSeason2Overview.tsx'));
for(const path of ['app.json','eas.json','package.json','package-lock.json'])assert.equal(fs.readFileSync(path,'utf8'),execFileSync('git',['show','7b19459c09494f36210e1b3b7017bedf0868ec8d:'+path],{encoding:'utf8'}),'Unrelated/native config changed: '+path);
const all=loadPlayerCatalogue();assert.equal(all.length,20223);assert.equal(crypto.createHash('sha256').update(JSON.stringify(all.filter(p=>!['recent-50545314','recent-50590296',...JSON.parse(fs.readFileSync('assets/data/totw7Cards20261028.json')).map(c=>c.id)].includes(p.id)))).digest('hex'),'27e3cc3dcb38484049468bf481fbba6c222cba3c8b478b506561dbf0870e6d36');
console.log('Home/formations passed: 29 Season 2 cards retained, 20,198 original cards unchanged; two Showdown versions added; corrected Holding/Defend/Attack roles and visible depth; every saved slot ID preserved; native runtime/config unchanged. Production base:',base);
